def solve(rows):
    if not rows:
        return []

    # Audit filter
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 5 != 2 or i == len(rows) - 1:
            filtered_rows.append(row)

    # Rotate
    if filtered_rows:
        rotated_rows = filtered_rows[2:] + filtered_rows[:2]
    else:
        rotated_rows = []

    # Sort and deduplicate
    sorted_rows = sorted(list(set(rotated_rows)))

    # Sessionize
    sessions = []
    if sorted_rows:
        current_session = [sorted_rows[0], sorted_rows[0], 1]
        for i in range(1, len(sorted_rows)):
            if sorted_rows[i] - current_session[1] > 8:
                sessions.append(current_session)
                current_session = [sorted_rows[i], sorted_rows[i], 1]
            else:
                current_session[1] = sorted_rows[i]
                current_session[2] += 1
        sessions.append(current_session)

    return sessions

